//! #3004 P4-1: the files the generators wrote before the hook command name changes from
//! `moai-cli` to `moai` (P4-2) and the status line default follows (P4-3). The fixtures under
//! `tests/fixtures/hooks-pre-p4/` were captured by running the tip generator (`hooks-plan` /
//! `hooks-apply`, `claude-settings-plan` / `-apply`) in a temporary project with a temporary
//! HOME, before this card changed any generated byte. This test regenerates each file the same
//! way and compares bytes, so the P4-2 flip has to move the fixtures deliberately, one file at
//! a time, and a change that moves them by accident fails here. The receipts carry no
//! timestamp and no path, so nothing is normalized.
#![cfg(unix)]

use moai_cli::{claude, hooks};
use serde_json::{json, Map, Value};
use std::{fs, path::Path};
use tempfile::TempDir;

const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/hooks-pre-p4");

/// A fresh project with the state folder and a separate HOME, both temporary.
fn project() -> (TempDir, std::path::PathBuf, std::path::PathBuf) {
    let dir = TempDir::new().unwrap();
    let root = fs::canonicalize(dir.path()).unwrap();
    let project = root.join("project");
    let home = root.join("home");
    fs::create_dir_all(project.join(".moai-cli")).unwrap();
    fs::create_dir_all(&home).unwrap();
    (dir, project, home)
}

fn install(project: &Path, home: &Path, host: &str, lane: hooks::LaneLoop) {
    let plan = hooks::plan_with(project, host, Some(home), lane.clone()).unwrap();
    let digest = plan["plan_digest"].as_str().unwrap().to_string();
    hooks::apply_with(project, host, Some(home), &digest, "fixture", lane).unwrap();
}

/// Compares `project/<generated>` with `FIXTURES/<fixture>` byte for byte.
fn same(project: &Path, generated: &str, fixture: &str) {
    let got = fs::read(project.join(generated)).unwrap();
    let want = fs::read(Path::new(FIXTURES).join(fixture)).unwrap();
    assert_eq!(
        String::from_utf8_lossy(&got),
        String::from_utf8_lossy(&want),
        "{generated} no longer matches tests/fixtures/hooks-pre-p4/{fixture}"
    );
    assert_eq!(got, want, "{generated} differs from {fixture} in bytes");
}

#[test]
fn claude_project_settings_and_receipt_match_the_pre_p4_bytes() {
    let (_d, project, home) = project();
    install(&project, &home, "claude", hooks::LaneLoop::Keep);
    same(&project, ".claude/settings.json", "claude.settings.json");
    same(
        &project,
        ".moai-cli/manifests/claude-settings.json",
        "claude.receipt.json",
    );
}

#[test]
fn codex_hooks_file_and_receipt_match_the_pre_p4_bytes() {
    let (_d, project, home) = project();
    install(&project, &home, "codex", hooks::LaneLoop::Keep);
    same(&project, ".codex/hooks.json", "codex.hooks.json");
    same(
        &project,
        ".moai-cli/manifests/codex-hooks.json",
        "codex.receipt.json",
    );
}

#[test]
fn omp_extension_and_receipt_match_the_pre_p4_bytes() {
    let (_d, project, home) = project();
    install(&project, &home, "omp", hooks::LaneLoop::Keep);
    same(
        &project,
        ".omp/extensions/moai-hooks.ts",
        "omp.moai-hooks.ts",
    );
    same(
        &project,
        ".moai-cli/manifests/omp-hooks.json",
        "omp.receipt.json",
    );
}

#[test]
fn the_codex_lane_stop_group_matches_the_pre_p4_bytes() {
    let (_d, project, home) = project();
    let lane = hooks::LaneLoop::Set {
        lane: "agent-1".into(),
        repo: "o/r".into(),
    };
    install(&project, &home, "codex", lane);
    same(&project, ".codex/hooks.json", "codex-lane.hooks.json");
    same(
        &project,
        ".moai-cli/manifests/codex-hooks.json",
        "codex-lane.receipt.json",
    );
}

#[test]
fn an_owned_status_line_matches_the_pre_p4_bytes() {
    let (_d, project, _home) = project();
    let mut input = Map::new();
    input.insert(
        "statusLine".into(),
        json!({"type": "command", "command": "moai-cli statusline"}),
    );
    let desired = claude::user_settings_desired(&project, &input).unwrap();
    let plan = claude::settings_plan(&project, &desired).unwrap();
    let digest = plan["plan_digest"].as_str().unwrap().to_string();
    let applied: Value = claude::settings_apply(&project, &desired, &digest, "fixture").unwrap();
    assert!(applied.is_object(), "{applied}");
    same(
        &project,
        ".claude/settings.json",
        "statusline.settings.json",
    );
    same(
        &project,
        ".moai-cli/manifests/claude-settings.json",
        "statusline.receipt.json",
    );
}
